import{_ as o,a as s,b as i,c,d as l}from"./Pagetitle.vue_vue_type_script_setup_true_lang-e9dd489f.js";import{_ as q}from"./SeihoTestLayout-7f62b74d.js";import{o as b,a as r,w as a,b as u,h as t}from"./app-f2f2ccd6.js";import"./_plugin-vue_export-helper-c27b6911.js";const m={class:"bg-gray-100 py-10 text-gray-800"},T={class:"mx-auto mt-4 max-w-4xl space-y-2"},e="ファイナンシャルプラニングとコンプライアンス",n="2025年度 フォームC",x={__name:"Fp2025c",setup(N){return(j,_)=>(b(),r(q,{title:e},{default:a(()=>[u("section",m,[t(o,{title:e,description:n}),u("div",T,[t(s,{questionNumber:1,title:e,subject:n,questionTitle:"生命保険ＦＰの役割",contents:["ファイナンシャル・プランナーとは、ファイナンシャル・プランニングを行うエキスパートであり、プランを立てる際に必要に応じて、[[弁護士、税理士、不動産の専門家などの協力を得ながら]]、お客さまの総合的な資産設計を行い、その実行の手助けをすることを主たる職務とする。","正しい","お客さまの考え方の複雑化・多様化に対応し、一人ひとりのお客さまに対する「[[オーダーメイド設計]]」が強く求められるようになった。","子どもの結婚資金 → 子どもの教育資金"]}),t(s,{questionNumber:2,title:e,subject:n,questionTitle:"ライフプランニングの基礎",contents:["生保ＦＰがライフイベントを決めるのではなく、一般的なライフイベントを示すことによって、[[お客さまの希望を聞き出すような姿勢]]が重要である。","正しい","[[ライフサイクル表]]の作成は、お客さまのライフプランニングを行ううえでの第一歩であり、次に作成する[[キャッシュフロー表]]の前提となる。","キャッシュフローとは、各年における家計のフロー（収入と支出）から把握される資金の収支と、[[その結果増減するストック（貯蓄残高）のこと]]である。"]}),t(s,{questionNumber:3,title:e,subject:n,questionTitle:"リスクマネジメント",contents:["正しい","死亡に伴うリスクには、その人の死亡によって予定外の大きな支出が[[発生するものもある]]。","生命保険だけ → 生命保険と損害保険","老後生活資金の準備は、[[生命保険商品だけではなく、さまざまな金融商品で対応することができる]]。"]}),t(s,{questionNumber:4,title:e,subject:n,questionTitle:"金融ビッグバンによる金融システムの規制緩和後の資産運用",contents:["金融システムの規制緩和により、「外為の規制[[緩和]]」「金融機関の垣根の[[撤廃]]」「外国資本の[[参入]]」、そして「金融新商品の登場」など、金融業界は大変革を遂げた。","正しい","金融機関の選択から金融商品の選択まで、運用に関することもすべて[[お客さまの自己責任で行う]]ことが求められるようになった。","資産設計においては、[[種類別分散や時間的分散、通貨的分散等を取り入れ]]、リスクとリターンのバランスを考慮して[[分散投資を行い]]、常に最適のポートフォリオを考える必要がある。"]}),t(s,{questionNumber:5,title:e,subject:n,questionTitle:"住宅取得資金計画",contents:["購入金額の1割 → 購入金額の2割","自己資金を積み立てるための金融商品の選択基準は、収益性だけでなく、気に入った物件が見つかった場合、すぐに手付金等が準備できるような[[流動性も求められる]]。","正しい","初年度に確定申告した会社員等の場合は、次年度以降の確定申告は[[必要ない]]。"]}),t(s,{questionNumber:6,title:e,subject:n,questionTitle:"金融商品のリスク",contents:["集中投資 → 分散投資","潜在化 → 顕在化","だれもが安全で高い収益が得られる商品を選びたいと望むが、実際には、「絶対に安全で高い収益や利回り」が得られる商品は[[存在しない]]。","正しい"]}),t(s,{questionNumber:7,title:e,subject:n,questionTitle:"老後生活設計の基礎知識",contents:["近所付き合いの費用・趣味や「生きがい」のための費用など「定年によって発生する支出」もあるので、生活費（消費部分）は[[極端に少なくなることはない]]。","[[平均余命に10年を加算する]]などお客さまが長生きに対する不安を感じないように、必要年数を設定する必要がある。","老後生活資金の不足額が[[異なる]]ため、プランニングも[[異なる]]。","正しい"]}),t(s,{questionNumber:8,title:e,subject:n,questionTitle:"老後の保障",contents:["高齢者の医療費自己負担が増える傾向にあるので、生命保険会社の[[医療保険などによる医療保障の充実]]が必要になる。","夫の生命保険の家族特約として妻の医療保障を確保している場合、夫の死亡時に妻の医療保障がなくなる可能性があるため、[[妻の医療保障を単体で準備するのが望ましい]]。","正しい","公的介護保険にも[[1割（一定以上所得のある人は2割または3割）]]の自己負担があるため、日常生活を営むうえで経済的負担が大きい。"]}),t(s,{questionNumber:9,title:e,subject:n,questionTitle:"相続税の計算手順",contents:["相続財産評価額の合計額から、非課税財産・葬式費用・債務を差し引き、相続開始前[[7年]]以内の贈与財産を加算して課税価格合計額を算出する。ただし、相続開始前[[3年超7年以内]]の贈与は、総額100万円まで加算しない。","課税価格合計額から遺産に係る基礎控除（[[3,000万円]] + [[600万円]] × 法定相続人の数）を行い算出する。","相続放棄した者も法定相続人に[[加える]]。","正しい"]}),t(s,{questionNumber:10,title:e,subject:n,questionTitle:"保険業法",contents:["保険業務や保険契約に関する法律は「保険監督法」と「保険取引法」に大別できるが、保険監督法に[[保険業法]]が含まれ、保険取引法に[[民法と保険法]]が関係する。","正しい","保険契約の内容や効力に関する法律は、[[民法と保険法]]が中心になるが、実際の保険契約の詳細は保険約款の定めによる。","保険業法は、[[保険事業にのみ]]認められる相互会社について、その組織・運営に関する規定を定めている。"]}),t(s,{questionNumber:11,title:e,subject:n,questionTitle:"犯罪による収益の移転防止に関する法律（犯罪収益移転防止法）",contents:["取引時確認において、お客さまが法人の場合、[[法人と実際の取引担当者双方の本人特定事項の確認が必要]]。","金融機関が一度取引時確認を行っているお客さまについて、次回以降の取引では取引時確認済みのお客さまであることを確認できれば、[[再度の取引時確認は不要]]である。","お客さまに隠ぺいの目的があった場合には、[[1年以下の拘禁刑もしくは100万円以下の罰金が科される（またはその併科）]]。","正しい"]}),t(s,{questionNumber:12,title:e,subject:n,questionTitle:"保険販売等に関する法律",contents:["正しい","生命保険募集人は、会社の行う各種手続きのために、マイナンバーを取得することもあるが、法令で限定的に定められている利用範囲を超えてマイナンバーを収集したり、[[お客さま管理のためにマイナンバーを利用したりしてはならない]]。","保険法 → 保険業法","金融商品販売業者等は、金融商品を販売するための「勧誘方針」を策定し、[[公表しなければならない]]。"]}),t(s,{questionNumber:13,title:e,subject:n,questionTitle:"キャッシュフロー表の作成",contents:["正しい","継続的な支出には、基本生活費・住居費（[[住宅ローン返済額を含む]]）・生命保険料・損害保険料などがある。","正しい","正しい"]}),t(s,{questionNumber:14,title:e,subject:n,questionTitle:"ライフステージ別のプランニング",contents:["正しい","人生の３大支出である「教育資金」「住宅資金」「老後生活資金」のうち、[[教育資金と住宅資金]]は、マネーポートフォリオの中心となる。","正しい","正しい"]}),t(s,{questionNumber:15,title:e,subject:n,questionTitle:"ローンの種類",contents:["正しい","正しい","金融機関の審査については、[[銀行の審査が一番厳しく]]、[[信販会社などは緩やか]]になっているのが一般的である。","正しい"]}),t(s,{questionNumber:16,title:e,subject:n,questionTitle:"独立行政法人住宅金融支援機構（「機構」）",contents:["正しい","「機構」が行う「財形住宅融資」の融資額は財形貯蓄残高の[[10倍]]の額（最高[[4,000万円]]）までで、住宅取得価額（リフォーム融資は住宅改良価額）の[[90％]]が限度である。","正しい","正しい"]}),t(s,{questionNumber:17,title:e,subject:n,questionTitle:"資金運用の３要素による金融商品の分類",contents:["正しい","普通預金は、「[[流動性]]」の高い商品に分類される。","正しい","正しい"]}),t(s,{questionNumber:18,title:e,subject:n,questionTitle:"金融商品のリスクの種類",contents:["正しい","貨幣価値の上昇 → 貨幣価値が下落","正しい","正しい"]}),t(s,{questionNumber:19,title:e,subject:n,questionTitle:"死亡保険金の活用方法等",contents:["正しい","正しい","正しい","遺族基礎年金の受給者である被保険者の妻に該当する場合、資産運用に[[障害者等のマル優・特別マル優の非課税の枠が利用できる]]。"]}),t(s,{questionNumber:20,title:e,subject:n,questionTitle:"老後の資金運用",contents:["正しい","正しい","正しい","老後の資金運用は、基本的に「[[安全性]]」が原則である。老後資金の運用は「収益性」「安全性」に「流動性」も加えたマネーマネジメントだけでなく、万一の入院等のために「リスクマネジメント」を十分考慮した[[バランスの良いマネーポートフォリオ]]が重要となる。"]}),t(s,{questionNumber:21,title:e,subject:n,questionTitle:"生命保険を活用した相続対策",contents:["正しい","正しい","この際注意すべきことは、他の相続人に渡す財産額は、[[遺留分相当額以上]]とすることである。","正しい"]}),t(s,{questionNumber:22,title:e,subject:n,questionTitle:"保険募集と禁止行為",contents:["お客さまの要望に沿った提案であっても、お客さまに現在の職業について事実と異なる告知を勧めることは禁止行為に[[該当する]]。","正しい","正しい","正しい"]}),t(s,{questionNumber:23,title:e,subject:n,questionTitle:"金融サービスの提供及び利用環境の整備等に関する法律（金融サービス提供法）",contents:["正しい","お客さまに「信用リスク」の説明が必要となる金融商品は、[[すべての保険種類]]が対象となる。","正しい","正しい"]}),t(s,{questionNumber:24,title:e,subject:n,questionTitle:"保険法",contents:["正しい","正しい","正しい","既払込保険料相当額 → 解約返戻金相当額"]}),t(i,{questionNumber:5,title:e,subject:n,questionRange:"25〜29",questionTitle:"ローン金利の種類",contents:["2","5","元金","変動金利型","短い"],labels:["エ","オ","キ","コ","ア"]}),t(i,{questionNumber:6,title:e,subject:n,questionRange:"30〜34",questionTitle:"教育資金設計",contents:["元利均等","育英年金","5,000円〜10,000円","給付型","住民税非課税世帯・準ずる世帯"],labels:["オ","イ","カ","ケ","ウ"]}),t(i,{questionNumber:7,title:e,subject:n,questionRange:"35〜39",questionTitle:"生命保険相談所・裁定審査会",contents:["生命保険協会","紛争解決","1ヶ月","ＡＤＲ","業務規程"],labels:["オ","ク","ア","カ","エ"]}),t(c,{questionNumber:40,title:e,subject:n,items:[{questionTitle:"外貨建金融商品の利用",content:"ライフプラン（生活設計）の実現を目指して、金融資産の運用効率を上げるためには、外貨建ての金融商品を利用することは通貨的分散の効果があるが、為替リスク等も考慮に入れる[[必要がある]]。"},{questionTitle:"リスクマネジメント",content:"正しい"},{questionTitle:"住宅ローンの借換え",content:"正しい"},{questionTitle:"住宅に対する考え方",content:"正しい"},{questionTitle:"教育資金設計",content:"[[学校外教育費]]には、[[学習塾や家庭教師・通信教育費といった補助学習費]]や芸術・文化活動・スポーツなどにかかる費用が含まれる。"},{questionTitle:"中途解約リスク",content:"正しい"},{questionTitle:"高齢者医療制度",content:"後期高齢者の場合、医療機関の窓口ではかかった費用の1割、[[所定水準以上の所得者の場合は2割（そのうち現役並み所得者は3割）]]を負担する。"},{questionTitle:"生命保険会社の経営破綻時の取引制限",content:"正しい"},{questionTitle:"消費者契約法に定める不適切な行為",content:"退去すべき旨の意思表示には、直接的な表現だけでなく、[[間接的な表現や身振り手振りも含まれる]]。"},{questionTitle:"保険募集における違法行為",content:"保険業法で規定されている保険募集における禁止行為は、[[行政処分を受ける可能性が生じる]]。"}]})]),t(l,{"previous-route":"daigaku.fp2025b","next-route":"daigaku.fp2024a","home-route":"daigaku.index"})])]),_:1}))}};export{x as default};
